∀ {α : Sort u} {β : Sort v} {γ : Sort w} {g : β → γ},
  @Function.Bijective.{v, w} β γ g →
    @Function.Bijective.{imax u v, imax u w} (α → β) (α → γ) fun x => @Function.comp.{u, v, w} α β γ g x

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β},
  @Function.Bijective.{u_1, u_2} α β f →
    @Function.Bijective.{imax u_2 u_3, imax u_1 u_3} (β → γ) (α → γ) fun g => @Function.comp.{u_1, u_2, u_3} α β γ g f

∀ {α : Sort u_1} {β : Sort u_2} {f : α → β},
  @Function.Bijective.{u_1, u_2} α β f →
    ∀ {p : β → Prop}, Iff (@ExistsUnique.{u_2} β fun y => p y) (@ExistsUnique.{u_1} α fun x => p (f x))

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β} {g : γ → α},
  @Function.Bijective.{u_3, u_2} γ β (@Function.comp.{u_3, u_1, u_2} γ α β f g) →
    @Function.Injective.{u_1, u_2} α β f → @Function.Bijective.{u_3, u_1} γ α g

∀ {ι : Sort u_1} {α : ι → Sort u_2} {β : ι → Sort u_3} {f : (i : ι) → α i → β i},
  (∀ (i : ι), @Function.Bijective.{u_2, u_3} (α i) (β i) (f i)) →
    @Function.Bijective.{imax u_1 u_2, imax u_1 u_3} ((i : ι) → α i) ((i : ι) → β i) (@Pi.map.{u_1, u_2, u_3} ι α β f)

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {δ : Sort u_4} {f : α → β} {g : α → γ},
  @Function.FactorsThrough.{u_1, u_2, u_3} α β γ g f →
    ∀ (g' : γ → δ), @Function.FactorsThrough.{u_1, u_2, u_4} α β δ (@Function.comp.{u_1, u_3, u_4} α γ δ g' g) f

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {δ : Sort u_4} {f : α → β} {g : α → γ},
  @Function.FactorsThrough.{u_1, u_2, u_3} α β γ g f →
    ∀ (g' : δ → α),
      @Function.FactorsThrough.{u_4, u_2, u_3} δ β γ (@Function.comp.{u_4, u_1, u_3} δ α γ g g')
        (@Function.comp.{u_4, u_1, u_2} δ α β f g')

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β} {g : α → γ},
  @Function.FactorsThrough.{u_1, u_2, u_3} α β γ g f →
    ∀ (e' : β → γ) (a : α), @Eq.{u_3} γ (@Function.extend.{u_1, u_2, u_3} α β γ f g e' (f a)) (g a)

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β} {g : α → γ} (e' : β → γ),
  @Function.FactorsThrough.{u_1, u_2, u_3} α β γ g f →
    @Eq.{imax u_1 u_3} (α → γ) (@Function.comp.{u_1, u_2, u_3} α β γ (@Function.extend.{u_1, u_2, u_3} α β γ f g e') f)
      g

∀ {α : Sort u_1} {β : Sort u_2} (r : β → β → Prop) {f : α → β},
  @Function.Injective.{u_1, u_2} α β f →
    ∀ [@Std.Antisymm.{u_2} β r], @Std.Antisymm.{u_1} α (@Function.onFun.{u_1, u_2, 1} α β Prop r f)

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β} {g : γ → α},
  @Function.Injective.{u_1, u_2} α β f →
    @Function.Injective.{u_3, u_1} γ α g →
      @Function.Surjective.{u_3, u_2} γ β (@Function.comp.{u_3, u_1, u_2} γ α β f g) →
        And (@Function.Bijective.{u_1, u_2} α β f) (@Function.Bijective.{u_3, u_1} γ α g)

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {g : β → γ},
  @Function.Injective.{u_2, u_3} β γ g →
    @Function.Injective.{imax u_1 u_2, imax u_1 u_3} (α → β) (α → γ) fun x => @Function.comp.{u_1, u_2, u_3} α β γ g x

∀ {α : Sort u_1} {β : Sort u_2} (p : α → Prop) [inst : @DecidablePred.{u_1} α p]
  {f : (@Subtype.{u_1} α fun a => p a) → β} {f' : (@Subtype.{u_1} α fun a => Not (p a)) → β},
  @Function.Injective.{max 1 u_1, u_2} (@Subtype.{u_1} α fun a => p a) β f →
    @Function.Injective.{max 1 u_1, u_2} (@Subtype.{u_1} α fun a => Not (p a)) β f' →
      (∀ {x x' : α} {hx : p x} {hx' : Not (p x')},
          @Ne.{u_2} β (f (@Subtype.mk.{u_1} α (fun a => p a) x hx))
            (f' (@Subtype.mk.{u_1} α (fun a => Not (p a)) x' hx'))) →
        @Function.Injective.{u_1, u_2} α β fun x =>
          @dite.{u_2} β (p x) (inst x) (fun h => f (@Subtype.mk.{u_1} α (fun a => p a) x h)) fun h =>
            f' (@Subtype.mk.{u_1} α (fun a => Not (p a)) x h)

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β},
  @Function.Injective.{u_1, u_2} α β f →
    ∀ (g : α → γ) (e' : β → γ) (a : α), @Eq.{u_3} γ (@Function.extend.{u_1, u_2, u_3} α β γ f g e' (f a)) (g a)

∀ {γ : Sort u_3} {α₁ : Sort u_4} {α₂ : Sort u_5} {α₃ : Sort u_6} {f₁₂ : α₁ → α₂},
  @Function.Injective.{u_4, u_5} α₁ α₂ f₁₂ →
    ∀ {f₂₃ : α₂ → α₃},
      @Function.Injective.{u_5, u_6} α₂ α₃ f₂₃ →
        ∀ (g : α₁ → γ) (e' : α₃ → γ),
          @Eq.{imax u_6 u_3} (α₃ → γ)
            (@Function.extend.{u_4, u_6, u_3} α₁ α₃ γ (@Function.comp.{u_4, u_5, u_6} α₁ α₂ α₃ f₂₃ f₁₂) g e')
            (@Function.extend.{u_5, u_6, u_3} α₂ α₃ γ f₂₃
              (@Function.extend.{u_4, u_5, u_3} α₁ α₂ γ f₁₂ g (@Function.comp.{u_5, u_6, u_3} α₂ α₃ γ e' f₂₃)) e')

∀ {α : Sort u_1} {β : Sort u_2} (r : β → β → Prop) {f : α → β},
  @Function.Injective.{u_1, u_2} α β f →
    ∀ [IsLinearOrder.{u_2} β r], IsLinearOrder.{u_1} α (@Function.onFun.{u_1, u_2, 1} α β Prop r f)

∀ {α : Type u_4} {β : Sort u_5} {f : α → β},
  @Function.Injective.{u_4 + 1, u_5} α β f →
    @Function.IsPartialInv.{u_4, u_5} α β f (@Function.partialInv.{u_4, u_5} α β f)

∀ {α : Sort u_1} {β : Sort u_2} (r : β → β → Prop) {f : α → β},
  @Function.Injective.{u_1, u_2} α β f →
    ∀ [IsPartialOrder.{u_2} β r], IsPartialOrder.{u_1} α (@Function.onFun.{u_1, u_2, 1} α β Prop r f)

∀ {α : Sort u_1} {β : Sort u_2} (r : β → β → Prop) {f : α → β},
  @Function.Injective.{u_1, u_2} α β f →
    ∀ [IsStrictTotalOrder.{u_2} β r], IsStrictTotalOrder.{u_1} α (@Function.onFun.{u_1, u_2, 1} α β Prop r f)

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β} {g : γ → α},
  @Function.Injective.{u_3, u_2} γ β (@Function.comp.{u_3, u_1, u_2} γ α β f g) →
    @Function.Surjective.{u_3, u_1} γ α g → @Function.Injective.{u_1, u_2} α β f

∀ {ι : Sort u_4} {α : ι → Sort u_5} {β : ι → Sort u_6} {f : (i : ι) → α i → β i},
  (∀ (i : ι), @Function.Injective.{u_5, u_6} (α i) (β i) (f i)) →
    @Function.Injective.{imax u_4 u_5, imax u_4 u_6} ((i : ι) → α i) ((i : ι) → β i) (@Pi.map.{u_4, u_5, u_6} ι α β f)

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β} [Nonempty.{u_3} γ],
  @Function.Injective.{u_1, u_2} α β f →
    @Function.Surjective.{imax u_2 u_3, imax u_1 u_3} (β → γ) (α → γ) fun g => @Function.comp.{u_1, u_2, u_3} α β γ g f

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β},
  @Function.Injective.{u_1, u_2} α β f →
    ∀ (g₀ : β → γ),
      @Function.Surjective.{imax u_2 u_3, imax u_1 u_3} (β → γ) (α → γ) fun g =>
        @Function.comp.{u_1, u_2, u_3} α β γ g f

∀ {α : Sort u_1} {β : Sort u_2} (r : β → β → Prop) {f : α → β},
  @Function.Injective.{u_1, u_2} α β f →
    ∀ [@Std.Trichotomous.{u_2} β r], @Std.Trichotomous.{u_1} α (@Function.onFun.{u_1, u_2, 1} α β Prop r f)

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β → γ},
  @Function.Injective2.{u_1, u_2, u_3} α β γ f →
    ∀ {a₁ a₂ : α} {b₁ b₂ : β}, Iff (@Eq.{u_3} γ (f a₁ b₁) (f a₂ b₂)) (And (@Eq.{u_1} α a₁ a₂) (@Eq.{u_2} β b₁ b₂))

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β → γ},
  @Function.Injective2.{u_1, u_2, u_3} α β γ f →
    ∀ [Nonempty.{u_2} β], @Function.Injective.{u_1, imax u_2 u_3} α (β → γ) f

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β → γ},
  @Function.Injective2.{u_1, u_2, u_3} α β γ f →
    ∀ [Nonempty.{u_1} α], @Function.Injective.{u_2, imax u_1 u_3} β (α → γ) fun b a => f a b

∀ {α : Type u_4} {β : Type u_5} {γ : Type u_6} {f : α → β → γ},
  @Function.Injective2.{u_4 + 1, u_5 + 1, u_6 + 1} α β γ f →
    @Function.Injective.{max (u_5 + 1) (u_4 + 1), u_6 + 1} (Prod.{u_4, u_5} α β) γ
      (@Function.uncurry.{u_4, u_5, u_6 + 1} α β γ f)

∀ {α : Sort u} {f : α → α},
  @Function.Involutive.{u} α f →
    ∀ (P : Prop) [inst : Decidable P] (x : α),
      @Eq.{u} α (f (@ite.{u} α P inst x (f x))) (@ite.{u} α (Not P) (@instDecidableNot P inst) x (f x))

∀ {α : Type u_4} {β : Type u_5} {γ : Sort u_6} {f : α → β} {g : β → Option.{u_4} α} {h : β → γ}
  {i : γ → Option.{u_5} β},
  @Function.IsPartialInv.{u_4, u_5 + 1} α β f g →
    @Function.IsPartialInv.{u_5, u_6} β γ h i →
      @Function.IsPartialInv.{u_4, u_6} α γ (@Function.comp.{u_4 + 1, u_5 + 1, u_6} α β γ h f) fun x =>
        @Option.bind.{u_5, u_4} β α (i x) g

∀ {α : Type u_4} {β : Sort u_5} {f : α → β} {g : β → Option.{u_4} α},
  @Function.IsPartialInv.{u_4, u_5} α β f g →
    ∀ (x : α), @Eq.{u_4 + 1} (Option.{u_4} α) (g (f x)) (@Option.some.{u_4} α x)

∀ {α : Type u_4} {β : Sort u_5} {f : α → β} {g : β → Option.{u_4} α},
  @Function.IsPartialInv.{u_4, u_5} α β f g →
    ∀ (x : β) (h : @Eq.{1} Bool (@Option.isSome.{u_4} α (g x)) Bool.true),
      @Eq.{u_5} β (f (@Option.get.{u_4} α (g x) h)) x

∀ {α : Type u_4} {β : Sort u_5} {f : α → β} {g : β → Option.{u_4} α},
  @Function.IsPartialInv.{u_4, u_5} α β f g →
    ∀ (x : α), @Function.Surjective.{u_5, u_4 + 1} β α fun x_1 => @Option.getD.{u_4} α (g x_1) x

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β} {g : β → α} {h : β → γ} {i : γ → β},
  @Function.LeftInverse.{u_2, u_1} β α f g →
    @Function.LeftInverse.{u_3, u_2} γ β h i →
      @Function.LeftInverse.{u_3, u_1} γ α (@Function.comp.{u_1, u_2, u_3} α β γ h f)
        (@Function.comp.{u_3, u_2, u_1} γ β α g i)

∀ {α : Sort u_1} {β : Sort u_2} {γ : β → Sort v} {f : α → β} {g : β → α} (h : @Function.LeftInverse.{u_1, u_2} α β g f)
  (C : (a : α) → γ (f a)) (a : α),
  @Eq.{v} (γ (f a)) (@Eq.rec.{v, u_2} β (f (g (f a))) (fun x x_1 => γ x) (C (g (f a))) (f a) ⋯) (C a)

∀ {α : Sort u_1} {β : Sort u_2} {γ : β → Sort v} {f : α → β} {g : β → α} (h : @Function.LeftInverse.{u_1, u_2} α β g f)
  (C : (a : α) → γ (f a)) (a : α),
  @Eq.{v} (γ (f a)) (@Eq.recOn.{v, u_2} β (f (g (f a))) (fun x x_1 => γ x) (f a) ⋯ (C (g (f a)))) (C a)

∀ {α : Sort u_1} {β : Sort u_2} {f : α → β} {g₁ g₂ : β → α},
  @Function.LeftInverse.{u_1, u_2} α β g₁ f →
    @Function.RightInverse.{u_1, u_2} α β g₂ f → @Eq.{imax u_2 u_1} (β → α) g₁ g₂

∀ {α : Sort u_1} {β : Sort u_2} {f : α → β} {g : β → α},
  @Function.LeftInverse.{u_2, u_1} β α f g →
    @Function.Injective.{u_1, u_2} α β f → @Function.RightInverse.{u_2, u_1} β α f g

∀ {α : Sort u_1} {β : Sort u_2} {f : α → β} {g : β → α},
  @Function.LeftInverse.{u_2, u_1} β α f g →
    @Function.Surjective.{u_2, u_1} β α g → @Function.RightInverse.{u_2, u_1} β α f g

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β} {g : β → α} {h : β → γ} {i : γ → β},
  @Function.RightInverse.{u_2, u_1} β α f g →
    @Function.RightInverse.{u_3, u_2} γ β h i →
      @Function.RightInverse.{u_3, u_1} γ α (@Function.comp.{u_1, u_2, u_3} α β γ h f)
        (@Function.comp.{u_3, u_2, u_1} γ β α g i)

∀ {α : Sort u_1} {β : Sort u_2} {f : α → β} {g : β → α},
  @Function.RightInverse.{u_2, u_1} β α f g →
    @Function.Injective.{u_2, u_1} β α g → @Function.LeftInverse.{u_2, u_1} β α f g

∀ {α : Sort u_1} {β : Sort u_2} {f : α → β} {g : β → α},
  @Function.RightInverse.{u_2, u_1} β α f g →
    @Function.Surjective.{u_1, u_2} α β f → @Function.LeftInverse.{u_2, u_1} β α f g

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β} {g : γ → α},
  @Function.Surjective.{u_1, u_2} α β f →
    @Function.Surjective.{u_3, u_1} γ α g →
      @Function.Injective.{u_3, u_2} γ β (@Function.comp.{u_3, u_1, u_2} γ α β f g) →
        And (@Function.Bijective.{u_1, u_2} α β f) (@Function.Bijective.{u_3, u_1} γ α g)

∀ {α : Sort u} {β : Sort v} {γ : Sort w} {g : β → γ},
  @Function.Surjective.{v, w} β γ g →
    @Function.Surjective.{imax u v, imax u w} (α → β) (α → γ) fun x => @Function.comp.{u, v, w} α β γ g x

∀ {α : Sort u_1} {β : Sort u_2} {f : α → β},
  @Function.Surjective.{u_1, u_2} α β f →
    ∀ {p : β → β → β → Prop}, Iff (∃ y₁ y₂ y₃, p y₁ y₂ y₃) (∃ x₁ x₂ x₃, p (f x₁) (f x₂) (f x₃))

∀ {α : Sort u_1} {β : Sort u_2} {f : α → β},
  @Function.Surjective.{u_1, u_2} α β f →
    ∀ {p : β → β → Prop}, Iff (∀ (y₁ y₂ : β), p y₁ y₂) (∀ (x₁ x₂ : α), p (f x₁) (f x₂))

∀ {α : Sort u_1} {β : Sort u_2} {f : α → β},
  @Function.Surjective.{u_1, u_2} α β f →
    ∀ {p : β → β → β → Prop}, Iff (∀ (y₁ y₂ y₃ : β), p y₁ y₂ y₃) (∀ (x₁ x₂ x₃ : α), p (f x₁) (f x₂) (f x₃))

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β},
  @Function.Surjective.{u_1, u_2} α β f →
    @Function.Injective.{imax u_2 u_3, imax u_1 u_3} (β → γ) (α → γ) fun g => @Function.comp.{u_1, u_2, u_3} α β γ g f

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β} {g : γ → α},
  @Function.Surjective.{u_3, u_2} γ β (@Function.comp.{u_3, u_1, u_2} γ α β f g) →
    @Function.Injective.{u_1, u_2} α β f → @Function.Surjective.{u_3, u_1} γ α g

∀ {ι : Sort u_1} {α : ι → Sort u_2} {β : ι → Sort u_3} {f : (i : ι) → α i → β i},
  (∀ (i : ι), @Function.Surjective.{u_2, u_3} (α i) (β i) (f i)) →
    @Function.Surjective.{imax u_1 u_2, imax u_1 u_3} ((i : ι) → α i) ((i : ι) → β i) (@Pi.map.{u_1, u_2, u_3} ι α β f)

∀ {ι : Sort u_1} [inst : DecidableEq.{u_1} ι] {α : ι → Sort u_2} {β : ι → Sort u_3} {γ : ι → Sort u_4}
  (f : (i : ι) → α i → β i → γ i) (g : (i : ι) → α i) (h : (i : ι) → β i) (i : ι) (v : α i) (w : β i) (j : ι),
  @Eq.{u_4} (γ j) (f j (@Function.update.{u_1, u_2} ι α inst g i v j) (@Function.update.{u_1, u_3} ι β inst h i w j))
    (@Function.update.{u_1, u_4} ι γ inst (fun k => f k (g k) (h k)) i (f i v w) j)

∀ {α : Type u_1} {β : Type u_2} {γ : Sort u_3},
  @Function.Injective.{imax (max (u_2 + 1) (u_1 + 1)) u_3, imax (u_1 + 1) (u_2 + 1) u_3} (Prod.{u_1, u_2} α β → γ)
    (α → β → γ) (@Function.curry.{u_1, u_2, u_3} α β γ)

∀ {α : Sort u} {β : α → Sort v} [inst : DecidableEq.{u} α] (f : (a : α) → β a) {a : α} {b : β a}
  (p : (a : α) → β a → Prop),
  Iff (∃ x, p x (@Function.update.{u, v} α β inst f a b x)) (Or (p a b) (∃ x, And (@Ne.{u} α x a) (p x (f x))))

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β},
  @Function.Injective.{u_1, u_2} α β f →
    ∀ (g : α → γ) (e' : β → γ),
      @Eq.{imax u_1 u_3} (α → γ)
        (@Function.comp.{u_1, u_2, u_3} α β γ (@Function.extend.{u_1, u_2, u_3} α β γ f g e') f) g

∀ {α : Sort u_1} {β : Sort u_2} {γ : Sort u_3} {f : α → β},
  @Function.Injective.{u_1, u_2} α β f →
    ∀ (e' : β → γ),
      @Function.Injective.{imax u_1 u_3, imax u_2 u_3} (α → γ) (β → γ) fun g =>
        @Function.extend.{u_1, u_2, u_3} α β γ f g e'

∀ {α : Sort u} {β : α → Sort v} [inst : DecidableEq.{u} α] (f : (a : α) → β a) {a : α} {b : β a}
  (p : (a : α) → β a → Prop),
  Iff (∀ (x : α), p x (@Function.update.{u, v} α β inst f a b x)) (And (p a b) (∀ (x : α), @Ne.{u} α x a → p x (f x)))

∀ {α α' : Sort u} {β : α → Sort v} {β' : α' → Sort v} {f : (a : α) → β a} {f' : (a : α') → β' a},
  @Eq.{u + 1} (Sort u) α α' →
    (∀ (a : α) (a' : α'), @HEq.{u} α a α' a' → @HEq.{v} (β a) (f a) (β' a') (f' a')) →
      @HEq.{imax u v} ((a : α) → β a) f ((a : α') → β' a) f'

∀ {α : Type u_4} {β : Sort u_5} {f : α → β} {g : β → Option.{u_4} α},
